import React from "react";

/**
 * A single glyph from the SubHub Icon Library, rendered as a CSS mask so it
 * inherits currentColor.
 *
 * The glyphs live in this artifact's own asset store — no external CDN, no
 * third-party icon set. ICON_BLOBS below is generated by the weekly Figma sync
 * and holds every icon in the library; ICON_ALIAS maps the legacy Lucide slugs
 * the system was originally built on to their library names.
 *
 * NEVER hand-author an icon here, paste one in from another set, or let a model
 * draw one. An unknown name renders the `placeholder` glyph and logs a warning
 * rather than silently rendering nothing. If you need an icon the library does
 * not have, contact Nathan Maus (nmaus@subcontractorhub.com) to have it drawn in
 * the SubHub Icon Library in Figma; the weekly sync brings it across.
 */
import { ICON_BLOBS, ICON_ALIAS } from "./icon-blobs";

const ICON_MISSING = "placeholder";
/** Folder holding icons/<name>.svg. Override with window.SUBHUB_ICON_BASE. */
const ICON_BASE = (typeof window !== "undefined" && window.SUBHUB_ICON_BASE) ||
  "icons/";
const warned = new Set();

function iconUrl(name) {
  const key = ICON_BLOBS[name] ? name : ICON_ALIAS[name];
  const id = ICON_BLOBS[key];
  if (id) return `${ICON_BASE}${key}.svg`;
  if (!warned.has(name)) {
    warned.add(name);
    console.warn(
      `[SubHub Icon] "${name}" is not in the SubHub Icon Library, so the placeholder ` +
      `glyph is showing. Do not draw a replacement and do not paste in an icon from ` +
      `another set — this design system only ships icons drawn in the SubHub Icon ` +
      `Library in Figma. Contact Nathan Maus (nmaus@subcontractorhub.com) to have ` +
      `"${name}" drawn, and the weekly sync will bring it across.`
    );
  }
  return `${ICON_BASE}${ICON_MISSING}.svg`;
}

export function Icon({ name, size = 18, color = "var(--icon-default)", style, ...rest }) {
  const url = `url("${iconUrl(name)}")`;
  return (
    <span
      aria-hidden="true"
      style={{
        display: "inline-block",
        width: size,
        height: size,
        flex: "0 0 auto",
        backgroundColor: color,
        WebkitMaskImage: url,
        maskImage: url,
        WebkitMaskRepeat: "no-repeat",
        maskRepeat: "no-repeat",
        WebkitMaskSize: "contain",
        maskSize: "contain",
        WebkitMaskPosition: "center",
        maskPosition: "center",
        ...style,
      }}
      {...rest}
    />
  );
}
